// seed.js
//
// Eenmalige startinhoud voor de website van Christine ten Kate.
//
// Deze versie is geschreven op basis van een analyse van de vorige website
// (christine-tenkate.nl) en aangevuld/herschreven in eigen bewoording — geen
// letterlijke tekst van de oude site is overgenomen. Bedoeld als een stevige,
// kloppende basis; Christine kan alles hierna zelf verder verfijnen via de
// paginabewerker.
import { requireAdmin } from "./admin-auth.js";
import { db } from "../../js/firebase-init.js";
import {
  doc, setDoc, collection, query, where, getDocs, serverTimestamp,
} from "https://www.gstatic.com/firebasejs/10.13.0/firebase-firestore.js";

let idCounter = 0;
function bid() { return `seed${Date.now()}${idCounter++}`; }

function heading(text, level = 2, align = "left") { return { id: bid(), type: "heading", text, level, align }; }
function paragraph(html, align = "left") { return { id: bid(), type: "text", html: `<p>${html}</p>`, align }; }
function list(items, align = "left") { return { id: bid(), type: "text", html: `<ul>${items.map((i) => `<li>${i}</li>`).join("")}</ul>`, align }; }
function quote(text, cite = "") { return { id: bid(), type: "quote", text, cite }; }
function divider() { return { id: bid(), type: "divider" }; }
function spacer(height = 30) { return { id: bid(), type: "spacer", height }; }
function faq(items) { return { id: bid(), type: "faq", items }; }
function tilesBlock(items) { return { id: bid(), type: "tiles", items }; }
function reviewsBlock(title, items) { return { id: bid(), type: "reviews", title, items }; }
function columns(n, items) { return { id: bid(), type: "columns", columns: n, items }; }
function imageBlock({ mediaId, alt = "", caption = "", align = "center", widthPercent }) {
  return { id: bid(), type: "image", mediaId, alt, caption, align, widthPercent };
}

